&lt;p&gt;&lt;a href="https://media2.dev.to/dynamic/image/width=800%2Cheight=%2Cfit=scale-down%2Cgravity=auto%2Cformat=auto/https%3A%2F%2Fdev-to-uploads.s3.us-east-2.amazonaws.com%2Fuploads%2Farticles%2Fjjjkclz2hcadh6wgn71n.png" class="article-body-image-wrapper"&gt;&lt;img src="https://media2.dev.to/dynamic/image/width=800%2Cheight=%2Cfit=scale-down%2Cgravity=auto%2Cformat=auto/https%3A%2F%2Fdev-to-uploads.s3.us-east-2.amazonaws.com%2Fuploads%2Farticles%2Fjjjkclz2hcadh6wgn71n.png" alt="Plate I Morning Steam running Recorded Sample Trace showing FOCUS SHARP 87%, Center Ceramic Cup spotlight, SHUTTER ARMED, and developed cobalt marginalia" width="800" height="500"&gt;&lt;/a&gt;&lt;br&gt;
